('vi', '32c7dc70-a486-4d9c-8fb8-e9696206713d|note|6', '''give me'' -> ''gimme''.'),
('vi', '32c7dc70-a486-4d9c-8fb8-e9696206713d|note|7', '''could you'' -> ''couldja'' /kʊdʒə/.'),
