('vi', '32c7dc70-a486-4d9c-8fb8-e9696206713d|note|13', '''must have'' -> ''musta'' /mʌstə/.'),
('vi', '32c7dc70-a486-4d9c-8fb8-e9696206713d|note|14', '''might have'' -> ''mighta'' /maɪtə/.'),
('vi', '32c7dc70-a486-4d9c-8fb8-e9696206713d|note|15', '''used to'' -> ''usta'' /juːstə/.'),
