('vi', '32c7dc70-a486-4d9c-8fb8-e9696206713d|note|17', '''need to'' -> ''needa''; ''to'' -> /də/.'),
('vi', '32c7dc70-a486-4d9c-8fb8-e9696206713d|note|18', '''to'' -> /də/; ''for'' -> /fər/.'),
